function isBinaryFile(filePath) {
    try {
        // Read first 8KB to check for binary content
        const fd = openSync(filePath, "r");
        const buf = Buffer.alloc(8192);
        const bytesRead = readSync(fd, buf, 0, 8192, 0);
        closeSync(fd);
        for (let i = 0; i < bytesRead; i++) {
            if (buf[i] === 0)
                return true; // Null byte → binary
        }
        return false;
    }
    catch {
        return false; // If we can't read, let downstream handle it
    }
}
async function validateInputs(inputs) {
    const valid = [];
    const cwd = process.cwd();
    for (const input of inputs) {
        // Resolve to absolute path safely
        let abs;
        try {
            abs = validateAndResolve(input, cwd);
        }
        catch (error) {
            console.warn(chalk.red(`  ✗ Rejected: ${input} — ${error instanceof Error ? error.message : String(error)}`));
            continue;
        }
        // Check existence
        if (!existsSync(abs)) {
            console.warn(chalk.red(`  ✗ Rejected: ${input} — file not found`));
            continue;
        }
        const stat = statSync(abs);
        // Handle directories: skip with note (pipeline expects files)
        if (stat.isDirectory()) {
            console.warn(chalk.yellow(`  ⚠ Skipped directory: ${input} — pass individual files instead`));
            continue;
        }
        if (!stat.isFile()) {
            console.warn(chalk.red(`  ✗ Rejected: ${input} — not a regular file`));
            continue;
        }
        // Check file extension
        const ext = extname(abs).toLowerCase();
        if (!SUPPORTED_EXTENSIONS.has(ext)) {
            console.warn(chalk.red(`  ✗ Rejected: ${input} — unsupported extension "${ext}" (supported: ${[...SUPPORTED_EXTENSIONS].join(", ")})`));
            continue;
        }
        // Check file size: reject if > 1MB, warn if > 100KB
        if (stat.size > REJECT_SIZE_THRESHOLD) {
            console.warn(chalk.red(`  ✗ Rejected: ${input} — file too large (${(stat.size / 1024 / 1024).toFixed(2)} MB, max 1 MB)`));
            continue;
        }
        if (stat.size > WARN_SIZE_THRESHOLD) {
            console.warn(chalk.yellow(`  ⚠ Warning: ${input} is large (${(stat.size / 1024).toFixed(1)} KB) — processing may be slow`));
        }
        // Check for binary content
        if (isBinaryFile(abs)) {
            console.warn(chalk.red(`  ✗ Rejected: ${input} — appears to be a binary file`));
            continue;
        }
        valid.push(abs);
    }
    if (valid.length === 0 && inputs.length > 0) {
        throw new Error("No valid input files after validation. Check paths, extensions, and file sizes.");
    }
    return valid;
}
